func findGeoName(ctx context.Context, country, region string) (string, string) {
	geodb := geo.Get(ctx)
	if geodb == nil {
		panic("Location.Lookup: ")
	}

	hasRegions := geodb.Metadata().DatabaseType == "City"
	iter := geodb.DB().Data()
	for iter.Next() {
		var r struct {
			Country struct {
				ISOCode string            `maxminddb:"iso_code"`
				Names   map[string]string `maxminddb:"names"`
			} `maxminddb:"country"`
			Subdivisions []struct {
				ISOCode string            `maxminddb:"iso_code"`
				Names   map[string]string `maxminddb:"names"`
			} `maxminddb:"subdivisions"`
		}
		err := iter.Data(&r)
		if err != nil {
			log.Error(context.Background(), err)
			return "", ""
		}

		// If we're looking for a specific region, only match when we find both country and region
		if region != "" && r.Country.ISOCode == country && len(r.Subdivisions) > 0 && r.Subdivisions[0].ISOCode == region {
			return r.Country.Names["en"], r.Subdivisions[0].Names["en"]
		}

		// For country-only databases or when no region is requested, match on country
		if region == "" && r.Country.ISOCode == country && !hasRegions {
			return r.Country.Names["en"], ""
		}

		// For city databases when no region is requested
		if region == "" && r.Country.ISOCode == country {
			return r.Country.Names["en"], ""
		}
	}
	return "", ""
}
EOF
```

